<script setup lang="ts">
import {ref,watch} from 'vue';
const props=defineProps<{authorization:string;caseRef?:string}>();
type Problem={caseRef:string;topic:string;version:number;quality:string;indexState:string;projection:{customer_goal:string;unresolved_question:string}};
type Group={groupRef:string;title:string;topic:string;version:number;caseCount?:number;members?:Problem[];sources?:Record<string,number>;history?:Array<{action:string;createdAt:string}>;analyses?:Array<{analysisRef:string;state:string;result?:string}>};
const groups=ref<Group[]>([]),group=ref<Group|null>(null),problem=ref<Problem|null>(null),candidates=ref<Array<{score:number;case:Problem}>>([]),coverage=ref<Record<string,number>>({}),error=ref(''),busy=ref(false),title=ref(''),crossTopic=ref(false),days=ref(30),evidence=ref(''),improvement=ref(''),method=ref('regression');
type SummaryStatement={text:string;source_refs:string[]};
type SummaryDetail={state:string;reviewState:string;summaryVersion:number;errorCode?:string;summary?:{customer_goal:SummaryStatement|null;unresolved_question:SummaryStatement|null;handling_steps:Array<SummaryStatement&{result_kind:string}>;uncertainty_notes:string[]}};
const summary=ref<SummaryDetail|null>(null),editGoal=ref(''),editQuestion=ref('');
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api/handoff-management/semantic'+path,{method,headers:{Authorization:props.authorization,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(data.detail||'操作未完成，请刷新并核对权限、内容或版本。');}return r.json();}
async function run(work:()=>Promise<void>){busy.value=true;error.value='';try{await work();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){await run(async()=>{groups.value=await api('/groups');coverage.value=await api('/coverage?days='+days.value);});}
watch(()=>props.authorization,()=>{group.value=null;problem.value=null;candidates.value=[];void load();},{immediate:true});
watch(()=>props.caseRef,()=>{problem.value=null;summary.value=null;candidates.value=[];void refreshProblem();},{immediate:true});
async function refreshProblem(){if(!props.caseRef)return;await run(async()=>{problem.value=await api('/cases/'+props.caseRef);const loaded:SummaryDetail=await api('/cases/'+props.caseRef+'/summary');summary.value=loaded;editGoal.value=loaded.summary?.customer_goal?.text||'';editQuestion.value=loaded.summary?.unresolved_question?.text||'';});}
async function correctSummary(){if(!props.caseRef||!summary.value)return;const version=summary.value.summaryVersion;await run(async()=>{await api('/cases/'+props.caseRef+'/summary','POST',{version,customer_goal:editGoal.value,unresolved_question:editQuestion.value});summary.value=await api('/cases/'+props.caseRef+'/summary');problem.value=await api('/cases/'+props.caseRef);});}
async function retrySummary(){if(!props.caseRef||!summary.value)return;await run(async()=>{await api('/cases/'+props.caseRef+'/summary/retry?version='+summary.value!.summaryVersion,'POST');summary.value=await api('/cases/'+props.caseRef+'/summary');});}
async function search(){if(!problem.value)return;await run(async()=>{const data=await api('/cases/'+problem.value!.caseRef+'/similar?days='+days.value+'&crossTopic='+crossTopic.value);candidates.value=data.candidates;});}
async function select(g:Group){await run(async()=>{group.value=await api('/groups/'+g.groupRef);});}
async function create(){await run(async()=>{group.value=await api('/groups','POST',{requestRef:crypto.randomUUID(),title:title.value,topic:problem.value?.topic||'general'});groups.value=await api('/groups');title.value='';});}
async function member(p:Problem,action:string){if(!group.value)return;await run(async()=>{group.value=await api('/groups/'+group.value!.groupRef+'/members','POST',{requestRef:crypto.randomUUID(),version:group.value!.version,caseRef:p.caseRef,action,basis:'same_primary_issue'});coverage.value=await api('/coverage?days='+days.value);});}
async function analyze(){if(!group.value)return;await run(async()=>{await api('/groups/'+group.value!.groupRef+'/analyses','POST',{requestRef:crypto.randomUUID(),version:group.value!.version});group.value=await api('/groups/'+group.value!.groupRef);});}
async function review(ref:string){await run(async()=>{await api('/analyses/'+ref+'/review','POST');group.value=await api('/groups/'+group.value!.groupRef);});}
async function link(){if(!group.value)return;await run(async()=>{const reviewed=group.value!.analyses?.find(a=>a.state==='REVIEWED');await api('/groups/'+group.value!.groupRef+'/evidence','POST',{improvementRef:improvement.value,version:group.value!.version,analysisRef:reviewed?.analysisRef||null,method:method.value,evidence:evidence.value});});}
async function rebuild(){await run(async()=>{await api('/rebuild','POST');coverage.value=await api('/coverage?days='+days.value);});}
function draft(value?:string){try{return JSON.parse(value||'{}');}catch{return {};}}
</script>
<template>
<section class="problem-groups"><h3>发现重复问题</h3><p>先看相似候选，再人工确认共同的主要问题。相似分数不是概率，关联问题不必归入同一组。</p>
<p v-if="error" role="alert">{{error}}</p>
<label>窗口 <select v-model="days" @change="load"><option :value="7">近7天</option><option :value="30">近30天</option></select></label>
<p>记录案件 {{coverage.total||0}} · 内容足够 {{coverage.contentReady||0}} · 已索引 {{coverage.indexed||0}} · 已归组 {{coverage.grouped||0}} · 待归组 {{(coverage.total||0)-(coverage.grouped||0)}}</p>
<details><summary>索引维护</summary><p>索引缺失或更新后可从有效问题记录重建，不重新创建案件。</p><button :disabled="busy" @click="rebuild">重建相似索引</button></details>
<article v-if="problem"><h4>当前问题</h4><p v-if="summary?.state==='SUCCEEDED'">{{problem.projection.customer_goal}}：{{problem.projection.unresolved_question||'未提供具体问题'}}</p><p v-else>案件已创建，具体问题以有效摘要为准。</p><p>内容 {{problem.quality}} · 索引 {{problem.indexState}}</p><label><input v-model="crossTopic" type="checkbox">跨业务主题搜索</label><button :disabled="busy||problem.indexState!=='READY'" @click="search">找相似案例</button><button :disabled="busy||!group||summary?.state!=='SUCCEEDED'||problem.quality!=='READY'" @click="member(problem,'add')">加入当前主问题组</button></article>
<article v-if="summary"><h4>问题摘要</h4><p>摘要 {{summary.state}}<template v-if="summary.summary"> · {{summary.reviewState==='HUMAN_REVIEWED'?'人工已复核':'AI 生成，未人工复核'}} · v{{summary.summaryVersion}}</template></p><p v-if="summary.state==='INSUFFICIENT_CONTEXT'">安全背景不足，案件处理不受影响。</p><p v-if="summary.state==='FAILED'">摘要未生成，可在尝试额度内重试；不会重新创建案件。{{summary.errorCode}}</p><button v-if="summary.state==='FAILED'" :disabled="busy" @click="retrySummary">重试摘要</button><button :disabled="busy" @click="refreshProblem">刷新摘要</button><template v-if="summary.summary"><p>目标：{{summary.summary.customer_goal?.text||'待明确'}}</p><p v-for="(s,i) in summary.summary.handling_steps" :key="i">已处理：{{s.text}}（{{s.result_kind==='assistant_explanation'?'助手曾解释，非核验事实':'执行结果'}}）</p><p>未解决：{{summary.summary.unresolved_question?.text||'待明确'}}</p><p v-for="(n,i) in summary.summary.uncertainty_notes" :key="i">{{n}}</p><details><summary>人工纠正摘要</summary><input v-model="editGoal" maxlength="120" placeholder="具体目标"><textarea v-model="editQuestion" maxlength="240" placeholder="具体未解决的问题"/><button :disabled="busy" @click="correctSummary">保存新版本并重建索引</button></details></template></article>
<article v-for="c in candidates" :key="c.case.caseRef"><p>{{c.case.projection.customer_goal}}：{{c.case.projection.unresolved_question}} · 相似分数 {{c.score.toFixed(3)}}</p><button :disabled="busy||!group" @click="member(c.case,'add')">同一主要问题，加入组</button><button :disabled="busy||!group" @click="member(c.case,'reject_related')">相关但不同</button><button :disabled="busy||!group" @click="member(c.case,'reject_unrelated')">无关</button></article>
<h4>人工问题组</h4><input v-model="title" maxlength="120" placeholder="例如：换货材料说明不清楚"><button :disabled="busy||title.length<2" @click="create">创建问题组</button>
<div><button v-for="g in groups" :key="g.groupRef" :disabled="busy" @click="select(g)">{{g.title}}</button></div>
<article v-if="group"><h4>{{group.title}} · {{group.caseCount}} 个独立案件</h4><p>多个问题时只按本组主要障碍计数，其他问题仍保留在案例描述中。</p><p v-for="p in group.members" :key="p.caseRef">{{p.projection.unresolved_question}} <button :disabled="busy" @click="member(p,'remove')">移出</button></p>
<button :disabled="busy||(group.caseCount||0)<2" @click="analyze">生成分析草案</button><button :disabled="busy" @click="select(group)">刷新组与草案</button>
<p>来源：客户主动 {{group.sources?.customer_requested||0}}，接受系统建议 {{group.sources?.system_suggested_accepted||0}}。计数为本组仍有效的独立案件。</p><details><summary>人工修订记录</summary><p v-for="(h,i) in group.history" :key="i">{{h.action}} · {{h.createdAt}}</p></details>
<article v-for="a in group.analyses" :key="a.analysisRef"><p>分析状态：{{a.state}}</p><template v-if="a.result&&['DRAFT','REVIEWED'].includes(a.state)"><p>{{draft(a.result).shared_issue}}</p><p v-for="(h,i) in draft(a.result).hypotheses" :key="i">待验证假设：{{h.hypothesis}}；{{h.uncertainty}}</p><p v-for="(s,i) in draft(a.result).suggested_actions" :key="i">建议：{{s.action}}；验证：{{s.verification}}</p><p>{{draft(a.result).limitations}}</p><button v-if="a.state==='DRAFT'" :disabled="busy" @click="review(a.analysisRef)">已核对依据，采纳草案</button></template></article>
<h4>关联改进验证</h4><p>在下方创建改进事项后，填写其引用与实际验证证据，再推进关闭。</p><input v-model="improvement" placeholder="改进事项引用"><select v-model="method"><option value="regression">回归验证</option><option value="manual_review">人工复核</option><option value="before_after_observation">前后观察</option></select><input v-model="evidence" placeholder="验证报告路径或证据引用"><button :disabled="busy||!improvement||!evidence" @click="link">保存组版本和验证依据</button></article>
</section>
</template>
<style scoped>.problem-groups{padding:16px;background:#eff6ff;border-radius:12px;margin:16px 0}.problem-groups article{background:white;border:1px solid #cbd5e1;padding:12px;margin:10px 0}.problem-groups button,.problem-groups input,.problem-groups select{padding:8px;margin:4px}.problem-groups p{line-height:1.65}</style>
